const item = $input.first();
const stdout = item.json.stdout || '';
const stderr = item.json.stderr || '';

// 提取 hostname（第一个 ===HOSTNAME=== 后的行）
const hostnameMatch = stdout.match(/===HOSTNAME===\n([^\n]+)/);
const hostname = hostnameMatch ? hostnameMatch[1].trim() : 'Linux-Server';

// 提取日期
const dateMatch = stdout.match(/===DATE===\n([^\n]+)/);
const serverDate = dateMatch ? dateMatch[1].trim() : new Date().toISOString();

const now = new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false });

const prompt = `你是一位经验丰富的Linux运维工程师。请根据以下服务器监控数据，生成一封专业的HTML状态报告邮件正文。

【服务器监控原始数据】
${stdout}
${stderr ? '\n【标准错误输出】\n' + stderr : ''}

【输出要求】
1. 仅输出HTML片段，从第一个 <div> 开始，不要包含 <!DOCTYPE>/<html>/<head>/<body> 等外层标签
2. 使用内联CSS，整体宽度 ≤ 750px，字体使用系统中文字体栈
3. 邮件结构（按顺序）：
   a. 状态总览横幅：判断整体状态（正常/需关注/严重），对应绿色(#22c55e)/橙色(#f97316)/红色(#ef4444)背景
   b. 基本信息卡片：主机名、服务器时间、系统运行时长、1/5/15分钟负载均值
   c. 资源使用情况：内存（已用/总量/百分比）、磁盘（每个挂载点已用百分比，>80%高亮橙色，>90%高亮红色）、CPU温度
   d. 容器与服务：Docker容器列表及状态、失败的systemd服务（如有，用红色高亮）
   e. 错误日志摘要：最近错误日志按严重程度归纳（如无错误则显示「近期无异常日志」）
   f. 操作建议：仅当存在异常时输出，给出具体的排查/处理建议
4. 状态判断标准：磁盘 >80% 为「需关注」，>90% 或有 failed 服务 为「严重」，error 日志为「需关注」
5. 全程使用中文，表格/卡片布局，专业简洁`;

return [{
  json: {
    hostname,
    serverDate,
    timestamp: now,
    rawOutput: stdout,
    geminiRequest: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 4096
      }
    }
  }
}];

const geminiResp = $input.first().json;
const ctx = $('解析数据 / 构建Gemini请求').first().json;
const hostname = ctx.hostname || '服务器';
const timestamp = ctx.timestamp || new Date().toLocaleString('zh-CN');

let aiBody = '';
try {
  aiBody = geminiResp.candidates[0].content.parts[0].text;
  // 去掉 Gemini 可能包裹的 markdown 代码块
  aiBody = aiBody.replace(/^```html\s*/m, '').replace(/^```\s*/m, '').replace(/\s*```$/m, '').trim();
} catch(e) {
  aiBody = `<div style="background:#fff3cd;border:1px solid #ffc107;border-radius:6px;padding:16px;margin:8px 0;">
  <strong style="color:#856404;">⚠️ AI 内容生成失败，以下为原始数据</strong>
  <pre style="font-size:11px;overflow:auto;white-space:pre-wrap;margin-top:8px;">${(ctx.rawOutput || '').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre>
</div>`;
}

const fullHtml = `<div style="font-family:'PingFang SC',Helvetica,Arial,sans-serif;max-width:750px;margin:0 auto;color:#1e293b;">
  <div style="background:linear-gradient(135deg,#0f2027 0%,#203a43 50%,#2c5364 100%);color:#fff;padding:22px 28px;border-radius:8px 8px 0 0;">
    <h2 style="margin:0;font-size:19px;font-weight:600;letter-spacing:0.3px;">&#x1F5A5; Linux 服务器状态报告</h2>
    <p style="margin:6px 0 0;font-size:12px;opacity:0.7;">${hostname}&nbsp;&nbsp;·&nbsp;&nbsp;${timestamp}</p>
  </div>
  <div style="border:1px solid #e2e8f0;border-top:none;background:#fff;border-radius:0 0 8px 8px;padding:24px 28px;">
    ${aiBody}
  </div>
  <div style="text-align:center;padding:14px;color:#94a3b8;font-size:11px;">
    &#x1F4EC; 此邮件由 n8n 自动生成 &nbsp;·&nbsp; NanoPi R6S &nbsp;·&nbsp; ${timestamp}
  </div>
</div>`;

return [{
  json: {
    subject: `[${hostname}] 服务器状态报告 · ${timestamp}`,
    html: fullHtml
  }
}];
